#include <bits/stdc++.h>using namespace std;#define int long longconst int N = 2e5 + 10;int T,n,m,ans;vector<int> G[N];void O_o(){    ans = 0;    cin >> n >> m;    for(int i=1;i<=n;i++){        G[i].clear();    }    for(int i=1;i<=m;i++){        int u,v;cin >> u >> v;        G[u].emplace_back(v);        G[v].emplace_back(u);    }    vector<int> clr(n + 1,-1);    for(int i=1;i<=n;i++){        if(clr[i] == -1){            queue<int> q;            bool ok = true;            vector<int> cnt(2,0);            q.push(i);            clr[i] = 0;            while(!q.empty()){                int u = q.front();                q.pop();                cnt[clr[u]]++;                for(auto &v : G[u]){                    if(clr[v] == -1){                        clr[v] = clr[u] ^ 1;                        q.push(v);                    }else if(clr[u] == clr[v]){                        ok = false;                    }                }            }            if(ok){                ans += max(cnt[0],cnt[1]);            }        }    }    cout << ans << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    cin >> T;    while(T--)O_o();    return 0;}